function validate([tickets, k]) {
  if (!Array.isArray(tickets) || tickets.length < 1 || tickets.length > 100) return 'tickets needs 1 to 100 people.';
  if (tickets.some(t => !Number.isInteger(t) || t < 1 || t > 100)) return 'Each person wants between 1 and 100 tickets.';
  if (!Number.isInteger(k) || k < 0 || k >= tickets.length) return 'k must be a valid index into tickets.';
  return null;
}

