function timeRequiredToBuy(tickets, k) {
  const remaining = [...tickets];
  let time = 0;

  while (true) {
    for (let i = 0; i < remaining.length; i++) {
      if (remaining[i] === 0) {
        continue;
      }
      remaining[i]--;
      time++;
      if (i === k && remaining[i] === 0) {
        return time;
      }
    }
  }
}

