function timeRequiredToBuy(tickets, k) {
  // Count directly: people up to k buy at most tickets[k], people after k at most tickets[k] - 1.
  let total = 0;
  tickets.forEach((t, i) => { total += Math.min(t, i <= k ? tickets[k] : tickets[k] - 1); });
  return total;
}

