function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(90, 100) : int(1, 6);
  const top = large ? 100 : (rand() < 0.5 ? 3 : 6);
  const tickets = Array.from({ length: n }, () => int(1, top));
  return [tickets, int(0, n - 1)];
}
